17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.samples.petclinic.util.AddressNormalizer;
46	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
47	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Maximum number of owners a single city may contain; creating an owner in a city that
66	     *  already has this many owners is rejected with 409 Conflict. */
67	    private static final int MAX_OWNERS_PER_CITY = 50;
68	
69	    /** Maximum number of owners that may be created on a single day (by registration date); creating
70	     *  an owner once this many owners already carry today's registration date is rejected with
71	     *  429 Too Many Requests. */
72	    private static final int MAX_OWNERS_PER_DAY = 100;
73	
74	    /** When more than this many owners already carry today's registration date at creation time, the
75	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
76	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
77	
78	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    private final TelephoneNormalizer telephoneNormalizer;
90	
91	    private final HouseholdNormalizer householdNormalizer;
92	
93	    private final AddressNormalizer addressNormalizer;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 HouseholdNormalizer householdNormalizer,
101	                                 AddressNormalizer addressNormalizer) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneNormalizer = telephoneNormalizer;
107	        this.householdNormalizer = householdNormalizer;
108	        this.addressNormalizer = addressNormalizer;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        normalizeOwnerFields(owner);
142	        // Enforce the pre-persistence policies that can reject the new owner outright.
143	        rejectDisallowedOwnerCreation(owner);
144	        // Identify any existing owners who share a household (same last name and address,
145	        // compared case-insensitively with collapsed whitespace) with the owner being created.
146	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
147	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
148	        // Reject creating an owner who shares a household with an existing owner, unless the
149	        // request explicitly opts in with 'sharesHousehold' true.
150	        if (!sharesHousehold && !householdMembers.isEmpty()) {
151	            throw new DuplicateHouseholdException(
152	                "An owner with the same last name and address already exists");
153	        }
154	        // When opting in and joining an existing household, assign the new owner and every
155	        // existing member the same stable household identifier derived from the last name and
156	        // address, so all owners of the household share one 'householdId'.
157	        if (sharesHousehold && !householdMembers.isEmpty()) {
158	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
159	            owner.setHouseholdId(householdId);
160	            for (Owner member : householdMembers) {
161	                if (!householdId.equals(member.getHouseholdId())) {
162	                    member.setHouseholdId(householdId);
163	                    this.clinicService.saveOwner(member);
164	                }
165	            }
166	        }
167	        // Record the size of this owner's household after this create, i.e. the number of owners
168	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
169	        // household counts the matched members plus itself; an owner without a shared household is a
170	        // household of one. Fixed at creation time and used to derive the 'GOLD' membership tier.
171	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
172	        // Record how many existing owners already share this owner's first and last name
173	        // (compared case-insensitively) before this create, fixed at creation time.
174	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
175	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
176	        // per-city sequence equal to one more than the owners already in that city, fixed at
177	        // creation time.
178	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
179	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
180	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
181	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
182	        // Flag the create when more than 80 owners have already been created on this owner's
183	        // (adjusted business-day) registration date, fixed at creation time.
184	        owner.setBulkSignupWarning(
185	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
186	        this.clinicService.saveOwner(owner);
187	        // Emit an audit line for the successful create, carrying the owner id, customer code and
188	        // registration date so the create can be traced from the dedicated AUDIT log.
189	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
190	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
191	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    /**
198	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
199	     * outright, in order, before any derived fields are assigned or the owner is saved. An owner
200	     * in a city that already contains {@link #MAX_OWNERS_PER_CITY} owners is rejected with 409
201	     * ({@link CityCapacityExceededException}), and an owner whose normalized telephone is already
202	     * used by another owner is rejected with 409 ({@link DuplicateTelephoneException}). Grouping the
203	     * independent create-time rejection rules here keeps {@link #addOwner} focused on the household,
204	     * derived-field and persistence steps. The household rule stays in {@link #addOwner} itself
205	     * because it shares the matched-member lookup with the shared household-id assignment.
206	     *
207	     * @param owner the newly mapped and normalized owner being created
208	     */
209	    private void rejectDisallowedOwnerCreation(Owner owner) {
210	        // Reject creating an owner once 100 or more owners already carry this owner's adjusted
211	        // business-day registration date.
212	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
213	            throw new DailyOwnerLimitExceededException(
214	                "The maximum number of owners that may be created today has already been reached");
215	        }
216	        // Reject creating an owner when the owner's city already contains 50 or more owners.
217	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
218	            throw new CityCapacityExceededException(
219	                "The city " + owner.getCity() + " already contains the maximum number of owners");
220	        }
221	        // Reject creating an owner whose normalized telephone is already used by another owner.
222	        String normalizedTelephone = owner.getTelephone();
223	        if (isTelephoneInUse(normalizedTelephone)) {
224	            throw new DuplicateTelephoneException(
225	                "An owner with telephone " + normalizedTelephone + " already exists");
226	        }
227	    }
228	
229	    /**
230	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
231	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
232	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
233	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
234	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
235	     * server's current date. Canonicalising the address here, before the household checks read it,
236	     * ensures duplicate detection and the shared household id both compare the normalized form.
237	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
238	     * duplicate, household and customer-code rules.
239	     *
240	     * @param owner the newly mapped owner to canonicalize
241	     */
242	    private void normalizeOwnerFields(Owner owner) {
243	        // Normalize the address on create so it is stored and returned in canonical form and every
244	        // later comparison (household duplicate detection and the shared household id) uses it.
245	        // A value that is blank after normalization is rejected with 400.
246	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
247	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
248	        // A value that cannot form a valid E.164 number is rejected with 400.
249	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
250	        // Store the (already syntactically validated) email lower-cased so it is persisted and
251	        // returned in canonical form. A missing email is left untouched.
252	        owner.setEmail(normalizeEmail(owner.getEmail()));
253	        // Default the registration date to the server's current date when the client did not
254	        // supply one, then roll the effective date forward to a business day so a Saturday or
255	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
256	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
257	        // date-derived field (such as the membership number's year segment) and the per-day
258	        // create-limit are computed from.
259	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
260	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
261	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
262	    }
263	
264	    /**
265	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
266	     * following Monday, while a weekday is returned unchanged. Applied to the effective
267	     * registration date (whether supplied in the request or defaulted to the server date) so the
268	     * persisted registration date, every value derived from it and the per-day create-limit all
269	     * use the adjusted business day.
270	     *
271	     * @param date the effective registration date
272	     * @return the same date if it is a weekday, otherwise the following Monday
273	     */
274	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
275	        java.time.LocalDate adjusted = date;
276	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
277	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
278	            adjusted = adjusted.plusDays(1);
279	        }
280	        return adjusted;
281	    }
282	
283	    /**
284	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
285	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
286	     * syntactically valid address (rejecting anything else with 400).
287	     *
288	     * @param email the email value (may be {@code null})
289	     * @return the lower-cased email, or {@code null} if the input was {@code null}
290	     */
291	    private String normalizeEmail(String email) {
292	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
293	    }
294	
295	    /**
296	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
297	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
298	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
299	     * the owners already in that city (e.g. 'LON-SMI-0007').
300	     *
301	     * @param city     the owner's city
302	     * @param lastName the owner's last name
303	     * @return the formatted customer code
304	     */
305	    private String nextCustomerCode(String city, String lastName) {
306	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
307	            .toUpperCase(java.util.Locale.ROOT);
308	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
309	            .toUpperCase(java.util.Locale.ROOT);
310	        int sequence = countOwnersInCity(city) + 1;
311	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
312	    }
313	
314	    /**
315	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
316	     * fix the per-city sequence of an owner's customer code at creation time.
317	     *
318	     * @param city the city of the owner being created
319	     * @return the number of existing owners in a matching city
320	     */
321	    private int countOwnersInCity(String city) {
322	        return (int) this.clinicService.findAllOwners().stream()
323	            .filter(existing -> existing.getCity() != null
324	                && existing.getCity().equalsIgnoreCase(city))
325	            .count();
326	    }
327	
328	    /**
329	     * Counts the existing owners whose registration date is the given adjusted business day. Used
330	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
331	     * owners already carry that business day as their registration date.
332	     *
333	     * @param date the adjusted business-day registration date to match
334	     * @return the number of existing owners registered on that date
335	     */
336	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
337	        return (int) this.clinicService.findAllOwners().stream()
338	            .filter(existing -> date.equals(existing.getRegistrationDate()))
339	            .count();
340	    }
341	
342	    /**
343	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
344	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
345	     *
346	     * @param customerCode     the owner's customer code
347	     * @param registrationDate the owner's registration date
348	     * @return the formatted membership number
349	     */
350	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
351	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
352	    }
353	
354	    /**
355	     * Determines whether the given normalized telephone is already used by an existing owner.
356	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
357	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
358	     * as the same number.
359	     *
360	     * @param normalizedTelephone the normalized (E.164) telephone to look for
361	     * @return {@code true} if another owner already uses this telephone
362	     */
363	    private boolean isTelephoneInUse(String normalizedTelephone) {
364	        if (normalizedTelephone == null) {
365	            return false;
366	        }
367	        return this.clinicService.findAllOwners().stream()
368	            .map(Owner::getTelephone)
369	            .map(telephoneNormalizer::normalize)
370	            .anyMatch(normalizedTelephone::equals);
371	    }
372	
373	    /**
374	     * Returns the existing owners who share the given household, i.e. have the same last name and
375	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
376	     * differing only in letter case or in incidental whitespace are treated as the same household.
377	     *
378	     * @param lastName the last name of the owner being created
379	     * @param address  the address of the owner being created
380	     * @return the existing owners with a matching last name and address (possibly empty)
381	     */
382	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
383	        String householdKey = householdNormalizer.householdKey(lastName, address);
384	        return this.clinicService.findAllOwners().stream()
385	            .filter(existing -> householdNormalizer
386	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
387	            .toList();
388	    }
389	
390	    /**
391	     * Counts the existing owners who share the given first and last name, compared
392	     * case-insensitively. Used to fix an owner's namesake count at creation time.
393	     *
394	     * @param firstName the first name of the owner being created
395	     * @param lastName  the last name of the owner being created
396	     * @return the number of existing owners with a matching first and last name
397	     */
398	    private int countNamesakes(String firstName, String lastName) {
399	        return (int) this.clinicService.findAllOwners().stream()
400	            .filter(existing -> existing.getFirstName() != null
401	                && existing.getFirstName().equalsIgnoreCase(firstName)
402	                && existing.getLastName() != null
403	                && existing.getLastName().equalsIgnoreCase(lastName))
404	            .count();
405	    }
406	
407	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
408	    @Override
409	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
410	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
411	        if (currentOwner == null) {
412	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
413	        }
414	        currentOwner.setAddress(ownerFieldsDto.getAddress());
415	        currentOwner.setCity(ownerFieldsDto.getCity());
416	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
417	        currentOwner.setLastName(ownerFieldsDto.getLastName());
418	        // Normalize the telephone to canonical E.164 form so it is stored and returned
419	        // consistently with create; an unformattable value is rejected with 400.
420	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
421	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
422	        this.clinicService.saveOwner(currentOwner);
423	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
424	    }
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Transactional
428	    @Override
429	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
430	        Owner owner = this.clinicService.findOwnerById(ownerId);
431	        if (owner == null) {
432	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
433	        }
434	        this.clinicService.deleteOwner(owner);
435	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Override
440	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
441	        Owner owner = this.clinicService.findOwnerById(ownerId);
442	        if (owner == null) {
443	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
444	        }
445	        HttpHeaders headers = new HttpHeaders();
446	        Pet pet = petMapper.toPet(petFieldsDto);
447	        owner.setId(ownerId);
448	        pet.setOwner(owner);
449	        pet.getType().setName(null);
450	        this.clinicService.savePet(pet);
451	        PetDto petDto = petMapper.toPetDto(pet);
452	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
453	            .buildAndExpand(pet.getId()).toUri());
454	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
455	    }
456	
457	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
458	    @Override
459	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
460	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
